/bin/bash -lc 'RUN_TMP=$(ls -td "$TMPDIR"/bhu-verify.* 2>/dev/null | head -1); python3 - "$RUN_TMP/admission.html" <<'"'PY'
import re,sys
s=open(sys.argv[1],encoding='utf-8').read()
for term in ['programType','visibleProgramType','levelOrder','visibleLevel','documentId','content']:
    vals=[]
    for m in re.finditer(term,s):
        vals.append(s[max(0,m.start()-250):m.start()+500])
    print('\\n---',term,'count',len(vals),'---')
    for x in vals[:5]: print(x[:800].replace('\\\\u0026','&'), '\\n')
PY"

/bin/bash -lc 'RUN_TMP=$(ls -td "$TMPDIR"/bhu-verify.* 2>/dev/null | head -1); python3 - "$RUN_TMP/admission.html" <<'"'PY'
import re,sys
s=open(sys.argv[1],encoding='utf-8').read()
for term in ['programType','visibleProgramType','levelOrder','visibleLevel','documentId','content']:
    vals=[]
    for m in re.finditer(term,s):
        vals.append(s[max(0,m.start()-250):m.start()+500])
    print('\\n---',term,'count',len(vals),'---')
    for x in vals[:5]: print(x[:800].replace('\\\\u0026','&'), '\\n')
PY"
